function createBond(
        address payable _emitter,
        address _owner,
        uint256 _percent,
        uint256 _expiration,
        uint256 _yearFee
    )
    internal
    returns(uint256)
    {
        Bond memory _bond = Bond(
            _emitter,
            _owner,
            msg.value,
            _percent,
            0,
            _expiration,
            _yearFee,
            0,
            0,
            0
        );
        uint256 _id = bonds.push(_bond).sub(1);
        emit BondCreated(_id, tx.origin, msg.value, _percent, _expiration, _yearFee);
        return _id;
    }

function createBond(
        address payable _emitter,
