6011816b", "kind": "state_variable", "name": "emitterFee()"}, {"id": "fragment-5f6757629e0abd8af9d2", "kind": "state_variable", "name": "ownerFee()"}, {"id": "fragment-b431557fb421ad5055ed", "kind": "state_variable", "name": "divider()"}, {"id": "fragment-381ed8235ab973e5d991", "kind": "state_variable", "name": "minEther()"}, {"id": "fragment-722d49913538b0959f4a", "kind": "state_variable", "name": "settings()"}, {"id": "fragment-a0bc5b0b88bd84a17290", "kind": "state_variable", "name": "bonds(uint256)"}], "provided_context": [{"id": "fragment-260a0e37710f420c2b10", "kind": "modifier", "name": "singleOwner(uint256)", "source": "modifier singleOwner(uint256 _id) {
