f2afb667d6fa7589298", "kind": "function", "name": "changeExpiration(uint256,uint256)"}, {"id": "fragment-14a10db8d1fc3b557138", "kind": "function", "name": "changeYearFee(uint256,uint256)"}, {"id": "fragment-15a94819b781c45df936", "kind": "function", "name": "takeEmitRequest(uint256)"}, {"id": "fragment-7a87533a575ded9025b3", "kind": "function", "name": "takeBuyRequest(uint256)"}, {"id": "fragment-481f70e6268a96b63bab", "kind": "function", "name": "finish(uint256)"}, {"id": "fragment-b5c6408b6d427a2d0f7f", "kind": "function", "name": "expire(uint256)"}, {"id": "fragment-b2432c1d53980b668f8c", "kind": "function", "name": "getBox(uint256)"}, {"id": "fragment-6b25e3c25fea5a812058", "kind": "function", "name": "fallback()"}, {"id": "fragment-9b9c9674608c6dd97371", "kind": "function", "name": "withdrawSystemETH(address)"}, {"id": "fragment-c697ffeffffa6f7dec57", "kind": "function", "name": "reclaimERC20(address,address)"}, {"id": "fragment-88a9d7f63fd6dd5a46a7", "kind": "function", "name": "setEmitterFee(uint256)"}, {"id": "fragment-102f988d36ac4877cf56", "kind": "function", "name": "setOwnerFee(uint256)"}, {"id": "fragment-10438a06cce5ee93a74f", "kind": "function", "name": "setMinEther(uint256)"}, {"id": "fragment-fd35af0355211cae677a", "kind": "function", "name": "changeAdmin(address)"}, {"id": "fragment-5799f12c5215aec885da", "kind": "function", "name": "precision()"}, {"id": "fragment-e8b72fe4985928608c3b", "kind": "function", "name": "rate()"}, {"id": "fragment-89a15613217ac9f70688", "kind": "modifier", "name": "onlyAdmin()"}, {"id": "fragment-41c72eed0e7bd48652a9", "kind": "modifier", "name": "onlyEmitter(uint256)"}, {"id": "fragment-260a0e37710f420c2b10", "kind": "modifier", "name": "singleOwner(uint256)"}, {"id": "fragment-b1429b29449808ac87ac", "kind": "modifier", "name": "emitRequest(uint256)"}, {"id": "fragment-525531ff732a4c2197fb", "kind": "modifier", "name": "buyRequest(uint256)"}, {"id": "fragment-08bb6606f7c8e5b354cb", "kind": "modifier", "name": "matched(uint256)"}, {"id": "fragment-ffbc17dabd17daba9ad0", "kind": "state_variable", "name": "admin()"}, {"id": "fragment-800739cc1f165c789fa9", "kind": "state_variable", "name": "systemETH()"}, {"id": "fragment-4ee3d7054dfe6011816b", "kind": "state_variable", "name": "emitterFee()"}, {"id": "fragment-5f6757629e0abd8af9d2", "kind": "state_variable", "name": "ownerFee()"}, {"id": "fragment-b431557fb421ad5055ed", "kind": "state_variable", "name": "divider()"}, {"id": "fragment-381ed8235ab973e5d991", "kind": "state_variable", "name": "minEther()"}, {"id": "fragment-722d49913538b0959f4a", "kind": "state_variable", "name": "settings()"}, {"id": "fragment-a0bc5b0b88bd84a17290", "kind": "state_variable", "name": "bonds(uint256)"}], "provided_context": [{"id": "fragment-31b8b1710aee85b740c7", "kind": "function", "name": "createBond(address,address,uint256,uint256,uint256)", "source": "function createBond(
        address payable _emitter,
        address _owner,
        uint256 _percent,
        uint256 _expiration,
        uint256 _yearFee
    )
    internal
    returns(uint256)
    {
        Bond memory _bond = Bond(
            _emitter,
            _owner,
            msg.value,
            _percent,
            0,
            _expiration,
            _yearFee,
            0,
            0,
            0
        );
        uint256 _id = bonds.push(_bond).sub(1);
        emit BondCreated(_id, tx.origin, msg.value, _percent, _expiration, _yearFee);
        return _id;
    }"}, {"id": "fragment-9c5bee888cd0284a5b9f", "kind": "function", "name": "leverage(uint256,uint256,uint256)", "source": "function leverage(uint256 _percent, uint256 _expiration, uint256 _yearFee) public payable returns (uint256) {
        require(msg.value >= minEther, "Too small funds");
        require(_percent >= ILogic(settings.logicManager()).withdrawPercent(msg.value), "Collateralization is not enough");
        require(_expiration >= 1 days && _expiration <= 365 days, "Expiration out of range");
        require(_yearFee <= 10000, "Fee out of range");

        return createBond(tx.origin, address(0), _percent, _expiration, _yearFee);
    }"}, {"id": "fragment-ba75975a6aaf0674b224", "kind": "function", "name": "exchange(uint256,uint256)", "source": "function exchange(uint256 _expiration, uint256 _yearFee) public payable returns (uint256) {
        require(msg.value >= minEther, "Too small funds");
        require(_expiration >= 1 days && _expiration <= 365 days, "Expiration out of range");
        require(_yearFee <= 10000, "Fee out of range");

        return createBond(address(0), tx.origin, 0, _expiration, _yearFee);
    }"}, {"id": "fragment-722cbffcc1c8abe19eb2", "kind": "function", "name": "close(uint256)", "source": "function close(uint256 _id) external singleOwner(_id) {
        uint256 _eth = bonds[_id].deposit;
        delete bonds[_id];
        msg.sender.transfer(_eth);
        emit BondClosed(_id, msg.sender);
    }"}, {"id": "fragment-481f70e6268a96b63bab", "kind": "function", "name": "finish(uint256)", "source": "function finish(uint256 _id) external onlyEmitter(_id) {

        // It's not need to check matching of the bond
        // since the expiration period cannot exceed 365 days.
        require(now < bonds[_id].expiration, "Bond expired");

        uint256 _secondsPast = now.sub(bonds[_id].createdAt);
        (uint256 _eth, uint256 _debt) = getBox(bonds[_id].tBoxId);

        uint256 _commission = bonds[_id].tmv.mul(_secondsPast).mul(bonds[_id].yearFee).div(365 days).div(divider);
        uint256 _sysTMV = _commission.mul(bonds[_id].sysFee).div(divider);

        address _owner = bonds[_id].owner;

        if (_sysTMV.add(_debt) > 0)
            IToken(settings.tmvAddress()).transferFrom(msg.sender, address(this), _sysTMV.add(_debt));
        if (_commission > 0)
            IToken(settings.tmvAddress()).transferFrom(msg.sender, _owner, _commission.sub(_sysTMV));

        if (_eth > 0) {
            ILogic(settings.logicManager()).close(bonds[_id].tBoxId);
            delete bonds[_id];
            msg.sender.transfer(_eth);
        } else {
            // when TBox no longer exists
            delete bonds[_id];
        }

        emit BondFinished(_id, msg.sender, _owner);
    }"}, {"id": "fragment-b5c6408b6d427a2d0f7f", "kind": "function", "name": "expire(uint256)", "source": "function expire(uint256 _id) external matched(_id) {

        require(now > bonds[_id].expiration, "Bond hasn't expired");


        (uint256 _eth, uint256 _tmv) = getBox(bonds[_id].tBoxId);

        if (_eth == 0) {
            emit BondExpired(_id, bonds[_id].emitter, bonds[_id].owner);
            delete bonds[_id];
            return;
        }

        if (_tmv != 0)
            _eth = ILogic(settings.logicManager()).withdrawableEth(bonds[_id].tBoxId);

        uint256 _commission = _eth.mul(bonds[_id].sysFee).div(divider);

        if (_commission > 0)
            ILogic(settings.logicManager()).withdrawEth(bonds[_id].tBoxId, _commission);

        systemETH = systemETH.add(_commission);

        ILogic(settings.logicManager()).transferFrom(address(this), bonds[_id].owner, bonds[_id].tBoxId);

        emit BondExpired(_id, bonds[_id].emitter, bonds[_id].owner);

        delete bonds[_id];
    }"}], "context_complete": false}

{"target": {"id": "fragment-0acd4fc671406bbe51c9", "kind": "function", "contract": "BondService", "signature": "changeDeposit(uint256,uint256)", "visibility": "internal", "source": "function changeDeposit(uint256 _id, uint256 _deposit) internal {
        uint256 _oldDeposit = bonds[_id].deposit;
        if (_deposit != 0 && _oldDeposit != _deposit) {
            require(_deposit >= minEther, "Too small funds");
            bonds[_id].deposit = _deposit;
            if (_oldDeposit > _deposit) {
                msg.sender.transfer(_oldDeposit.sub(_deposit));
            } else {
                require(msg.value == _deposit.sub(_oldDeposit), "Incorrect value");
            }
        }
    }", "state_reads": ["bonds", "minEther"], "state_writes": ["bonds"], "modifiers": [], "state_dependencies": [{"id": "BondService.bonds", "name": "bonds", "declaration_id": "fragment-a0bc5b0b88bd84a17290", "direct_writers": [{"fragment_id": "fragment-722cbffcc1c8abe19eb2", "signature": "close(uint256)", "kind": "function"}, {"fragment_id": "fragment-0acd4fc671406bbe51c9", "signature": "changeDeposit(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-2b44527ea3d7842622d5", "signature": "changePercent(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-1f2afb667d6fa7589298", "signature": "changeExpiration(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-14a10db8d1fc3b557138", "signature": "changeYearFee(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-15a94819b781c45df936", "signature": "takeEmitRequest(uint256)", "kind": "function"}, {"fragment_id": "fragment-7a87533a575ded9025b3", "signature": "takeBuyRequest(uint256)", "kind": "function"}, {"fragment_id": "fragment-481f70e6268a96b63bab", "signature": "finish(uint256)", "kind": "function"}, {"fragment_id": "fragment-b5c6408b6d427a2d0f7f", "signature": "expire(uint256)", "kind": "function"}]}, {"id": "BondService.minEther", "name": "minEther", "declaration_id": "fragment-381ed8235ab973e5d991", "direct_writers": [{"fragment_id": "fragment-8de60b94d695f3ccee5d", "signature": "constructor(ISettings)", "kind": "function"}, {"fragment_id": "fragment-10438a06cce5ee93a74f", "signature": "setMinEther(uint256)", "kind": "function"}]}], "preparation_mode": "FULL_INDEX"}, "available_context": [{"id": "fragment-d49da902bab3abd3bd8d", "kind": "function", "name": "create(uint256)"}, {"id": "fragment-c0764869ee4a491eb4fc", "kind": "function", "name": "precision()"}, {"id": "fragment-667c7d3aee170e52b0b2", "kind": "function", "name": "rate()"}, {"id": "fragment-3a00b5d10c5264bd6c7a", "kind": "function", "name": "transferFrom(address,address,uint256)"}, {"id": "fragmen