    }"}, {"id": "fragment-cc7a29d04fc883d38147", "kind": "function", "name": "changeOwner(uint256,uint256,uint256,uint256)", "source": "function changeOwner(uint256 _id, uint256 _deposit, uint256 _expiration, uint256 _yearFee)
