        if (_commission > 0)
            IToken(settings.tmvAddress()).transferFrom(msg.sender, _owner, _commission.sub(_sysTMV));

        if (_eth > 0) {
            ILogic(settings.logicManager()).close(bonds[_id].tBoxId);
            delete bonds[_id];
            msg.sender.transfer(_eth);
        } else {
