{"target": {"id": "fragment-481f70e6268a96b63bab", "kind": "function", "contract": "BondService", "signature": "finish(uint256)", "visibility": "external", "source": "function finish(uint256 _id) external onlyEmitter(_id) {

        // It's not need to check matching of the bond
        // since the expiration period cannot exceed 365 days.
        require(now < bonds[_id].expiration, "Bond expired");

        uint256 _secondsPast = now.sub(bonds[_id].createdAt);
        (uint256 _eth, uint256 _debt) = getBox(bonds[_id].tBoxId);

        uint256 _commission = bonds[_id].tmv.mul(_secondsPast).mul(bonds[_id].yearFee).div(365 days).div(divider);
        uint256 _sysTMV = _commission.mul(bonds[_id].sysFee).div(divider);

        address _owner = bonds[_id].owner;

        if (_sysTMV.add(_debt) > 0)
            IToken(settings.tmvAddress()).transferFrom(msg.sender, address(this), _sysTMV.add(_debt));
        if (_commission > 0)
            IToken(settings.tmvAddress()).transferFrom(msg.sender, _owner, _commission.sub(_sysTMV));

        if (_eth > 0) {
            ILogic(settings.logicManager()).close(bonds[_id].tBoxId);
            delete bonds[_id];
            msg.sender.transfer(_eth);
        } else {
            // when TBox no longer exists
            delete bonds[_id];
        }

        emit BondFinished(_id, msg.sender, _owner);
    }", "state_reads": ["bonds", "divider", "settings"], "state_writes": ["bonds"], "modifiers": [{"fragment_id": "fragment-41c72eed0e7bd48652a9", "name": "onlyEmitter", "state_reads": ["bonds"], "state_writes": []}], "state_dependencies": [{"id": "BondService.bonds", "name": "bonds", "declaration_id": "fragment-a0bc5b0b88bd84a17290", "direct_writers": [{"fragment_id": "fragment-722cbffcc1c8abe19eb2", "signature": "close(uint256)", "kind": "function"}, {"fragment_id": "fragment-0acd4fc671406bbe51c9", "signature": "changeDeposit(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-2b44527ea3d7842622d5", "signature": "changePercent(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-1f2afb667d6fa7589298", "signature": "changeExpiration(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-14a10db8d1fc3b557138", "signature": "changeYearFee(uint256,uint256)", "kind": "function"}, {"fragment_id": "fragment-15a94819b781c45df936", "signature": "takeEmitRequest(uint256)", "kind": "function"}, {"fragment_id": "fragment-7a87533a575ded9025b3", "signature": "takeBuyRequest(uint256)", "kind": "function"}, {"fragment_id": "fragment-481f70e6268a96b63bab", "signature": "finish(uint256)", "kind": "function"}, {"fragment_id": "fragment-b5c6408b6d427a2d0f7f", "signature": "expire(uint256)", "kind": "function"}]}, {"id": "BondService.divider", "name": "divider", "declaration_id": "fragment-b431557fb421ad5055ed", "direct_writers": []}, {"id": "BondService.settings", "name": "settings", "declaration_id": "fragment-722d49913538b0959f4a", "direct_writers": [{"fragment_id": "fragment-8de60b94d695f3ccee5d", "signature": "constructor(ISettings)", "kind": "function"}]}], "preparation_mode": "FULL_INDEX"}, "available_context": [{"id": "fragment-d49da902bab3abd3bd8d", "kind": "function", "name": "create(uint256)"}, {"id": "fragment-c0764869ee4a491eb4fc", "kind": "function", "name": "precision()"}, {"id": "fragment-667c7d3aee170e52b0b2", "kind": "function", 