        return ILogic(settings.logicManager()).boxes(_id);
    }"}, {"id": "fragment-3a00b5d10c5264bd6c7a", "kind": "function", "name": "transferFrom(address,address,uint256)", "source": "function transferFrom(address from, address to, uint256 tokenId) external;"}, {"id": "fragment-38ea9f182f35438692ba", "kind": "function", "name": "transferFrom(address,address,uint256)", "source": "function transferFrom(address from, address to, uint256 tokenId) external;"}, {"id": "fragment-722cbffcc1c8abe19eb2", "kind": "function", "name": "close(uint256)", "source": "function close(uint256 _id) external singleOwner(_id) {
