constructor(ISettings _settings) public {
        admin = msg.sender;
        settings = _settings;

        emitterFee = 500; // 0.5%
        emit BondEmitterFeeUpdated(emitterFee);

        ownerFee = 10000; // 10%
        emit BondOwnerFeeUpdated(ownerFee);

        minEther = 0.1 ether;
        emit BondMinEtherUpdated(minEther);
    }

