divider()"}, {"id": "fragment-381ed8235ab973e5d991", "kind": "state_variable", "name": "minEther()"}, {"id": "fragment-722d49913538b0959f4a", "kind": "state_variable", "name": "settings()"}, {"id": "fragment-a0bc5b0b88bd84a17290", "kind": "state_variable", "name": "bonds(uint256)"}], "provided_context": [{"id": "fragment-89a15613217ac9f70688", "kind": "modifier", "name": "onlyAdmin()", "source": "modifier onlyAdmin() {
        require(admin == msg.sender, "You have no access");
        _;
