a17290", "kind": "state_variable", "name": "bonds(uint256)"}], "provided_context": [{"id": "fragment-89a15613217ac9f70688", "kind": "modifier", "name": "onlyAdmin()", "source": "modifier onlyAdmin() {
        require(admin == msg.sender, "You have no access");
        _;
    }"}, {"id": "fragment-8de60b94d695f3ccee5d", "kind": "function", "name": "constructor(ISettings)", "source": "constructor(ISettings _settings) public {
        admin = msg.sender;
        settings = _settings;

        emitterFee = 500; // 0.5%
        emit BondEmitterFeeUpdated(emitterFee);

        ownerFee = 10000; // 10%
        emit BondOwnerFeeUpdated(ownerFee);

        minEther = 0.1 ether;
        emit BondMinEtherUpdated(minEther);
    }"}, {"id": "fragment-102f988d36ac4877cf56", "kind": "function", "name": "setOwnerFee(uint256)", "source": "function setOwnerFee(uint256 _value) external onlyAdmin {
        require(_value <= 50000, "Too much");
        ownerFee = _value;
        emit BondOwnerFeeUpdated(_value);
    }"}, {"id": "fragment-b431557fb421ad5055ed", "kind": "state_variable", "name": "divider()", "source": "uint256 public divider = 100000"}, {"id": "fragment-31b8b1710aee85b740c7", "kind": "function", "name": "createBond(address,address,uint256,uint256,uint256)", "source": "function createBond(
        address payable _emitter,
        address _owner,
        uint256 _percent,
        uint256 _expiration,
        uint256 _yearFee
    )
    internal
    returns(uint256)
    {
        Bond memory _bond = Bond(
            _emitter,
            _owner,
            msg.value,
            _percent,
            0,
            _expiration,
            _yearFee,
            0,
            0,
            0
        );
        uint256 _id = bonds.push(_bond).sub(1);
        emit BondCreated(_id, tx.origin, msg.value, _percent, _expiration, _yearFee);
        return _id;
    }"}, {"id": "fragment-8072a0d39d71f76dde34", "kind": "function", "name": "changeEmitter(uint256,uint256,uint256,uint256,uint256)", "source": "function changeEmitter(uint256 _id, uint256 _deposit, uint256 _percent, uint256 _expiration, uint256 _yearFee)
        external
        payable
        singleOwner(_id)
        onlyEmitter(_id)
    {
        changeDeposit(_id, _deposit);
        changePercent(_id, _percent);
        changeExpiration(_id, _expiration);
        changeYearFee(_id, _yearFee);

        emit BondChanged(_id, _deposit, _percent, _expiration, _yearFee, msg.sender);
    }"}], "context_complete": false}

